def task05_blur_roi(image):
    h,w=image.shape[:2]
    if min(h,w)<300: raise ValueError('Image must be at least 300x300')
    blurred=cv.GaussianBlur(image,(25,25),0)
    x,y=(w-300)//2,(h-300)//2
    return {'Original center 300x300':image[y:y+300,x:x+300],
